import{c as t,Q as a,j as r,m as s}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"DeepSWE replaces SWE-Bench Pro: Claude Code + Fable 5 leads at 77","description":"","frontmatter":{"url":"https://x.com/ArtificialAnlys/status/2065328920514515037","title":"DeepSWE replaces SWE-Bench Pro: Claude Code + Fable 5 leads at 77","author":"Artificial Analysis","archived":"2026-06-18T00:00:00.000Z","category":"anthropic-news","handle":"@ArtificialAnlys","published":"2026-06-12T00:00:00.000Z","score":7,"stats":"1943❤ · 185 retweets","tags":["deepswe","benchmark","claude-code","fable5","harness-quality","evaluation"],"type":"tweet-thread"},"headers":[],"relativePath":"research/tweets/2026-06-12-@ArtificialAnlys-515037.md","filePath":"research/tweets/2026-06-12-@ArtificialAnlys-515037.md","lastUpdated":1785909234000}'),d={name:"research/tweets/2026-06-12-@ArtificialAnlys-515037.md"};function i(l,e,o,n,h,c){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="deepswe-replaces-swe-bench-pro-claude-code-fable-5-leads-at-77-—-artificialanlys" tabindex="-1">DeepSWE replaces SWE-Bench Pro: Claude Code + Fable 5 leads at 77 — @ArtificialAnlys <a class="header-anchor" href="#deepswe-replaces-swe-bench-pro-claude-code-fable-5-leads-at-77-—-artificialanlys" aria-label="Permalink to &quot;DeepSWE replaces SWE-Bench Pro: Claude Code + Fable 5 leads at 77 — @ArtificialAnlys&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/ArtificialAnlys/status/2065328920514515037" target="_blank" rel="noreferrer">https://x.com/ArtificialAnlys/status/2065328920514515037</a><strong>類別</strong>：anthropic-news <strong>統計</strong>：1943❤ · 185 retweets</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>We&#39;ve updated the Artificial Analysis Coding Agent Index, replacing SWE-Bench Pro with Datacurve&#39;s DeepSWE benchmark - the swap lifts Codex with GPT-5.5 (xhigh) above Claude Code with Opus 4.8 (max), while the newly released Claude Fable 5 (max) in Claude Code debuts at the top</p><p>DeepSWE, built by @datacurve, writes its tasks from scratch rather than adapting them from public GitHub issues or pull requests, so no model has seen the solutions during training. That matters because SWE-Bench Pro, the benchmark it replaces in our Coding Agent Index, had grown gameable, with some models recovering the fix from the repository&#39;s commit history instead of solving the task.</p><p>The swap reorders the index: Codex with GPT-5.5 (xhigh) rises from 65 to 76, overtaking Claude Code with Opus 4.8 (max) at 73. Claude Code with Fable 5 (max), which enters directly on the refreshed index, leads at 77. SWE-Bench Pro had been flattering some combinations and penalizing others.</p><p>More below.</p><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>7/10</td><td>直接影響 Claude Code 模型選型（Fable 5=77&gt;Opus 4.8=73），harness quality 成獨立決策維度</td></tr><tr><td>B. 創新性 (20%)</td><td>8/10</td><td>引入 harness quality 作為評測第一變數，打破「模型能力=系統能力」的錯誤假設</td></tr><tr><td>C. 證據品質 (20%)</td><td>6/10</td><td>具體分數（77/76/73）、SWE-Bench Pro gameable 的技術解釋，推文上限 6</td></tr><tr><td>D. 技術深度 (15%)</td><td>7/10</td><td>解釋 DeepSWE 為何不可 game（任務從零生成）、why harness quality matters</td></tr><tr><td>E. 泛化性 (15%)</td><td>7/10</td><td>評測方法論的普遍影響：「系統評測」vs「模型評測」的認知轉移</td></tr><tr><td><strong>加權總分</strong></td><td><strong>7.0/10</strong></td><td>7×0.3+8×0.2+6×0.2+7×0.15+7×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule（model-selection-grid 更新，待人工審核） <strong>理由</strong>：DeepSWE 分數（Fable 5=77, Opus 4.8=73）應更新 .claude/refs/model-selection-grid.md，已在 EVOLUTION-QUEUE 中建立提案</p>',12)])])}const m=t(d,[["render",i]]);export{u as __pageData,m as default};
